  function applyWideAtlasLayout(resetView = true) {
    if (!body.classList.contains('atlas-wide') || typeof graphMode === 'undefined' || graphMode !== 'OVERVIEW' || !simulationNodes?.length) return;
    const singleExternalFocus = typeof focusSet !== 'undefined' && focusSet.size === 1;
    body.classList.toggle('atlas-external-focus',singleExternalFocus);

    if (singleExternalFocus) {
      for (const node of simulationNodes) node._atlasWideApplied = true;
      if (typeof drawPositions === 'function') drawPositions();
      if (resetView) {
        const xs=simulationNodes.map(n=>n.x), ys=simulationNodes.map(n=>n.y);
        const minX=Math.min(...xs), maxX=Math.max(...xs), minY=Math.min(...ys), maxY=Math.max(...ys);
        const spanX=Math.max(1,maxX-minX), spanY=Math.max(1,maxY-minY);
        const padX=window.innerWidth<=820?52:76, padY=window.innerWidth<=820?50:36;
        const fitX=(W-padX*2)/spanX, fitY=(H-padY*2)/spanY;
        scale=Math.max(window.innerWidth<=820?.62:.72,Math.min(.98,fitX,fitY));
        const midX=(minX+maxX)/2, midY=(minY+maxY)/2;
        tx=(W/2)-scale*midX;
        ty=(H/2)-scale*midY;
        if (typeof applyTransform === 'function') applyTransform();
      }
      const badge=document.getElementById('modeBadge');
      if (badge) badge.textContent='Фокус внешних связей';
      const hint=document.getElementById('wideMapHint');
      if (hint) {
        const title=hint.querySelector('strong'), text=hint.querySelector('span');
        if (title) title.textContent='Фокус внешних связей';
        if (text) text.textContent='В центре — выбранный узел · ближе к центру — основные органы и общие хабы · дальше — остальные внешние участники';
      }
      return;
    }

    const horizontal = window.innerWidth <= 820 ? 5.2 : 4.15;
    const vertical = window.innerWidth <= 820 ? 1.9 : 1.55;
    const centerX = W / 2, centerY = H / 2;
    const coreExtentX = Math.max(...simulationNodes.filter(n=>coreIds.has(n.id)).map(n=>Math.abs(n.x-centerX))) * horizontal;
    const peripheralStartX = coreExtentX + 100;
    let changed = false;
    for (const node of simulationNodes) {
      if (node._atlasWideApplied) continue;
      node.x = centerX + (node.x - centerX) * horizontal;
      node.y = centerY + (node.y - centerY) * vertical;
      // v205: bring peripheral participants closer without moving the ministries.
      const distanceX = Math.abs(node.x-centerX);
      if (!coreIds.has(node.id) && distanceX > peripheralStartX) node.x = centerX + Math.sign(node.x-centerX) * (peripheralStartX + (distanceX-peripheralStartX)*.65);
      node._atlasWideApplied = true;
      changed = true;
    }
    if (changed && typeof drawPositions === 'function') drawPositions();
    if (resetView) {
      scale = window.innerWidth <= 820 ? .88 : .96;
      tx = (W / 2) - scale * centerX;
      ty = (H / 2) - scale * centerY;
      if (typeof applyTransform === 'function') applyTransform();
    }
    const badge = document.getElementById('modeBadge');
    if (badge) badge.textContent = 'Обзор';
    const hint=document.getElementById('wideMapHint');
    if (hint) {
      const title=hint.querySelector('strong'), text=hint.querySelector('span');
      if (title) title.textContent='Широкая карта';
      if (text) text.textContent='Перемещайте карту мышью или пальцем · кнопка «−» раскрывает дальние связи';
    }
  }
