      const [id] = core;
      const departments = [...structureDeptById.values()].filter(row => row.Org === name);
      const documented = typeof structureDepartmentHandoffLinks === 'function'
        ? structureDepartmentHandoffLinks(id).filter(edge => edge.kind !== 'DEPARTMENT_CANDIDATE' && (edge.source_ids?.length || edge.source_url || edge.kind === 'DEPARTMENT_DOCUMENTED')) : [];
