      documented.forEach(edge => { if (degree.has(edge.a)) degree.set(edge.a,degree.get(edge.a)+1); if (degree.has(edge.b)) degree.set(edge.b,degree.get(edge.b)+1); });
      const top = departments.sort((a,b) => (degree.get(b.Dept_Global_ID)||0)-(degree.get(a.Dept_Global_ID)||0) || String(a.Registry_Name).localeCompare(String(b.Registry_Name),'ru')).slice(0,4);
