      cluster.querySelector('.atlas-feature-core')?.addEventListener('click', () => openMinistry(feature.id));
      cluster.querySelectorAll('[data-department-id]').forEach(button => button.addEventListener('click', () => openDepartment(feature.id, button.dataset.departmentId)));
      clustersHost.appendChild(cluster);
