    atlasEdges = typeof structureMinistryInteractionLinks === 'function'
      ? structureMinistryInteractionLinks().filter(edge => features.some(f => f.id === edge.a) && features.some(f => f.id === edge.b)) : [];
    requestAnimationFrame(renderAtlasLines);
