  focusChannel=function(id){const name=channelNodeById[id]?.name||channelState.nodeMap.get(id)?.name;setGraphMode('OVERVIEW');const input=[...toolbar.querySelectorAll('.channel-options137 input')].find(input=>input.value===name);if(input){input.checked=true;change179();}};
