(function(){
  if(typeof window.verifiedChannelLabels179!=='function')return;
  const toolbar181=document.getElementById('channelToolbar134');
  if(!toolbar181)return;

  /* The default overview has already been rendered at this point.
     Freeze exactly that main-map universe so detail/focus-only edges can never enter channel counts. */
  const MAIN_MAP_EDGE_IDS181=new Set(window.REN_CHANNEL_AUDIT244?Object.keys(window.REN_CHANNEL_AUDIT244.bindings):(simulationEdges||[]).filter(e=>e&&e.id).map(e=>e.id));
  const MAIN_MAP_NODE_IDS181=new Set();
  for(const e of DATA.edges){
    if(!MAIN_MAP_EDGE_IDS181.has(e.id))continue;
    MAIN_MAP_NODE_IDS181.add(e.a);MAIN_MAP_NODE_IDS181.add(e.b);
  }

  function channelRows181(){return [...toolbar181.querySelectorAll('.channel-options137 label[data-channel-row179]')];}
  function channelMeta181(){
    return channelRows181().map(row=>{
      const input=row.querySelector('input[type="checkbox"]');
      const dot=row.querySelector('.channel-dot137');
      return {row,input,name:input?.value||'',color:dot?.style.background||'#386C8E'};
    }).filter(x=>x.name);
  }
  function baselineCount181(name){
    let count=0;
    for(const e of DATA.edges){if(MAIN_MAP_EDGE_IDS181.has(e.id)&&window.verifiedChannelLabels179(e).includes(name))count++;}
    return count;
  }
  function visibleMainCount181(name){
    return (simulationEdges||[]).filter(e=>MAIN_MAP_EDGE_IDS181.has(e.id)&&window.verifiedChannelLabels179(e).includes(name)).length;
  }
  function refreshRows181(){
    const metas=channelMeta181();
    for(const m of metas){
      const total=baselineCount181(m.name);
      m.row.dataset.mainMapCount181=String(total);
      const badge=m.row.querySelector('[data-channel-count179]');
      if(badge){
        const visible=visibleMainCount181(m.name);
        badge.textContent=String(visible);
        badge.title='Подтверждённых рёбер этого канала на текущем виде главной карты: '+visible+(visible!==total?' · всего на главной карте без дополнительных фильтров: '+total:'');
      }
      m.row.hidden=total===0;
    }
    const box=toolbar181.querySelector('.channel-options137');
    if(box){
      const ordered=metas.slice().sort((a,b)=>baselineCount181(b.name)-baselineCount181(a.name)||a.name.localeCompare(b.name,'ru'));
      for(const m of ordered)box.appendChild(m.row);
    }
  }
  function selectedMainChannels181(e,optionMap){
    if(!MAIN_MAP_EDGE_IDS181.has(e.id))return [];
    const labels=window.verifiedChannelLabels179(e),out=[];
    for(const name of selectedChannels137){if(labels.includes(name)&&optionMap.has(name))out.push(optionMap.get(name));}
    return out;
  }

  paintChannels137=function(){
    if(graphMode!=='OVERVIEW')return;
    refreshRows181();defs137.replaceChildren();
    const optionMap=new Map(channelMeta181().map(x=>[x.name,{name:x.name,color:x.color}]));
    const em=new Map((simulationEdges||[]).map(e=>[e.id,e]));let visibleSelected=0,multi=0;
    for(const line of edgesLayer.querySelectorAll('.edge')){
      const e=em.get(line.dataset.id);if(!e)continue;
      const cs=selectedMainChannels181(e,optionMap);line.dataset.selectedChannels=cs.map(c=>c.name).join(';');let stroke='#a9afb5';
      if(cs.length===1)stroke=cs[0].color;
      if(cs.length>1){
        multi++;const gradient=document.createElementNS(ns137,'linearGradient');gradient.id='channel181-'+hashString(e.id).toString(16);
        gradient.setAttribute('gradientUnits','userSpaceOnUse');gradient.setAttribute('spreadMethod','repeat');gradient.setAttribute('data-repeat140','1');gradient.setAttribute('data-channel-count140',String(cs.length));
        const x1=Number(line.getAttribute('x1')||0),y1=Number(line.getAttribute('y1')||0),x2=Number(line.getAttribute('x2')||0),y2=Number(line.getAttribute('y2')||0),dx=x2-x1,dy=y2-y1,dist=Math.hypot(dx,dy)||1,cycle=Math.max(2,cs.length)*10;
        gradient.setAttribute('x1',x1);gradient.setAttribute('y1',y1);gradient.setAttribute('x2',x1+dx/dist*cycle);gradient.setAttribute('y2',y1+dy/dist*cycle);
        cs.forEach((c,i)=>{const from=i/cs.length,to=(i+1)/cs.length;for(const [offset,color] of [[from,c.color],[to,c.color]]){const stop=document.createElementNS(ns137,'stop');stop.setAttribute('offset',String(offset));stop.setAttribute('stop-color',color);gradient.appendChild(stop);}});
        defs137.appendChild(gradient);stroke='url(#'+gradient.id+')';
      }
      if(cs.length)visibleSelected++;
      line.style.setProperty('stroke',stroke,'important');line.style.setProperty('stroke-opacity',cs.length?'1':'0.38','important');line.style.setProperty('opacity','1','important');line.style.setProperty('stroke-width',cs.length?'3.4':'1.05','important');
    }
    const info=document.getElementById('channelMatch134');
    if(info){
      if(selectedChannels137.size)info.textContent='Подсвечено '+visibleSelected+' подтверждённых рёбер на главной карте'+(multi?' · '+multi+' многоканальных':'');
      else info.textContent='Главная карта: '+MAIN_MAP_NODE_IDS181.size+' узлов · '+MAIN_MAP_EDGE_IDS181.size+' связей';
    }
  };

  const help=toolbar181.querySelector('.channel-help137');
  if(help)help.innerHTML='<strong>Числа — только документально подтверждённые рёбра, отображаемые на главной карте.</strong> Внутренние, пользовательские и иные рёбра вне основной карты в счётчик не входят.';
  const search181=document.getElementById('channelSearch179');
  if(search181){
    search181.placeholder='Поиск канала главной карты…';
    search181.addEventListener('input',()=>{
      const q=search181.value.trim().toLocaleLowerCase('ru');
      for(const row of channelRows181()){
        const input=row.querySelector('input[type="checkbox"]'),name=input?.value||'',baseline=Number(row.dataset.mainMapCount181||0);
        row.hidden=baseline===0|| (!!q&&!name.toLocaleLowerCase('ru').includes(q));
      }
    });
  }

  DATA.channel_filter_v181={version:'v181',checked_on:'2026-10-03',mode:'DOCUMENTARY_CONFIRMED_MAIN_OVERVIEW_ONLY',main_map_nodes:MAIN_MAP_NODE_IDS181.size,main_map_edges:MAIN_MAP_EDGE_IDS181.size,note:'Счётчик и подсветка каналов ограничены подтверждёнными рёбрами основной широкой карты; рёбра вне главной карты исключены.'};
  refreshRows181();paintChannels137();
})();

