window.rosnedraDataContractHtml=function(e){const c=e?.data_contract;if(!c)return '';return '<div class="card rosnedra-contract" data-data-contract="'+esc(e.id)+'"><h4>'+esc(c.title)+'</h4><p><strong>Отправитель:</strong> '+esc(e.a_name||e.aName)+'<br><strong>Получатель:</strong> '+esc(e.b_name||e.bName)+'</p><details><summary>Состав передаваемых данных</summary><ul>'+c.fields.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul></details><p><strong>Когда:</strong> '+esc(c.trigger)+'</p><p><strong>Срок:</strong> '+esc(c.deadline)+'</p><p class="small">'+esc(c.recipient_role)+'</p></div>';};
function reorganize(html,nid){if(nid!==p.id&&!p.nodes.some(n=>n.id===nid))return html;const t=document.createElement('template');t.innerHTML=html;if(t.content.querySelector('[data-rosnedra-navigation]'))return html;
 // Keep the overview compact and put region navigation before reference material.
 if(nid===p.id){for(const card of t.content.querySelectorAll('.card')){const title=card.querySelector('h4');if(!title)continue;if(['Центральный аппарат','Территориальные органы','Территориальные фонды геологической информации','Региональный орган · самостоятельные полномочия'].includes(title.textContent)){const section=document.createElement('details'),summary=document.createElement('summary');section.className='card rosnedra-directory';summary.textContent=title.textContent+' · '+card.querySelectorAll('button').length;section.append(summary);title.remove();while(card.firstChild)section.append(card.firstChild);card.replaceWith(section);}}}
 for(const card of t.content.querySelectorAll('.card')){const title=card.querySelector('h4');if(!title||!title.textContent.includes(' → '))continue;const e=p.edges.find(e=>title.textContent===e.a_name+' → '+e.b_name);if(!e)continue;const section=document.createElement('details'),summary=document.createElement('summary');section.className='card rosnedra-flow';section.dataset.rosnedraFlow=e.id;summary.textContent=flowTitles[e.id]||e.data_contract?.title||e.processes;section.append(summary);const direction=document.createElement('p');direction.className='small';direction.textContent=e.a_name+' → '+e.b_name;section.append(direction);title.remove();while(card.firstChild)section.append(card.firstChild);card.replaceWith(section);}
 const header=t.content.querySelector('.meta');if(header)header.insertAdjacentHTML('afterend',window.rosnedraNavigationHtml(nid));else t.content.insertBefore(document.createRange().createContextualFragment(window.rosnedraNavigationHtml(nid)),t.content.firstChild);
 return t.innerHTML;
}
const oldNode=nodeDetail;nodeDetail=function(nid){return reorganize(oldNode(nid),nid);};
const oldStructure=structureNodeDetail;structureNodeDetail=function(nid){return reorganize(oldStructure(nid),nid);};
